<?php defined('ABSPATH') || exit;use GreatMarketrealmCompanion\Modules\DungeonMaster\Models\Location;$editing=$location instanceof Location;$currentParent=$editing?$location->parentId():'';$types=['realm'=>'Realm','region'=>'Region','settlement'=>'Settlement','district'=>'District','landmark'=>'Landmark','building'=>'Building','room'=>'Room / Chamber','dungeon'=>'Dungeon','wilderness'=>'Wilderness','other'=>'Other']; ?>
<form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="gmrc-gazetteer-form__body"><input type="hidden" name="action" value="gmrc_app_request"><input type="hidden" name="gmrc_route" value="<?php echo esc_attr($route); ?>"><input type="hidden" name="_method" value="<?php echo $editing?'PUT':'POST'; ?>"><input type="hidden" name="gmrc_nonce" value="<?php echo esc_attr(wp_create_nonce('gmrc_dm_gazetteer_'.$campaign->id())); ?>">
